import AppRoutes from './routes/AppRoutes'; 
import './App.css';

function App() {
    return (
    <Router>
    <div className="App">

      <Navbar />
      <header className="app-header">
        <h1>SafeParcel Management System</h1>
      </header>


      <main className="container">
        <AppRoutes />
      </main>

      {/* <Footer /> */}
    </div>
    </Router>
  );
}

export default App;
